const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,css='',extra='')=>`<button type="button" class="${css}" data-action="${action}" ${extra}>${text}</button>`;
const brand=()=>`<div class="brand"><div class="logo-mark">e</div><div><strong>EVOL DREAM</strong><small>CONTENT STUDIO</small></div></div>`;
const kindIcon={qualifications:'award',experts:'users',courses:'book',cases:'file'},featureTypes={qualifications:['张','资质'],cases:['个','案例']};
let state,me=null,users=[],leads=[],section='overview',editing=null,tab='zh',dirty=false,query='',statusFilter='',busy=false,simulateFail=false,schema=null,options=null;
let previewLang='zh',previewRecord=null;
const objectURLs=new Map();
const normalizeProductionCopy=()=>{document.querySelector('#simulate-fail')?.closest('label')?.remove();const replacements={'演示工作空间':'本地独立工作空间','浏览器演示记录':'本地更新记录','所有更改已保存于浏览器':'所有更改已保存到本地后台','模拟数据 · 不写入真实站点':'本地数据 · 发布后同步前台','前台模拟页':'本地前台'};const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);for(let node=walker.nextNode();node;node=walker.nextNode())for(const [from,to] of Object.entries(replacements))if(node.nodeValue.includes(from))node.nodeValue=node.nodeValue.replaceAll(from,to)};
new MutationObserver(normalizeProductionCopy).observe(app,{childList:true,subtree:true});
function mediaURL(file){if(!file)return '';if(file.id)return `/media/${encodeURIComponent(file.id)}`;if(!file.blob)return '';if(!objectURLs.has(file.blob))objectURLs.set(file.blob,URL.createObjectURL(file.blob));return objectURLs.get(file.blob);}
addEventListener('pagehide',()=>{for(const url of objectURLs.values())URL.revokeObjectURL(url)});
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3300);}
function ask(title,message,choices=[['cancel','取消'],['ok','确认','primary']],list=[]){return new Promise(resolve=>{modal.style.width='';modal.innerHTML=`<div class="dialog-body"><div class="eyebrow">CONTENT STUDIO</div><h2>${esc(title)}</h2><p>${esc(message)}</p>${list.length?`<ul class="dialog-list">${list.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</div><div class="dialog-actions">${choices.map(([value,label,css])=>`<button data-answer="${value}" class="${css||''}">${label}</button>`).join('')}</div>`;function finish(value){modal.close();modal.removeEventListener('cancel',cancel);resolve(value)}function cancel(e){e.preventDefault();finish('cancel')}modal.addEventListener('cancel',cancel);modal.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>finish(b.dataset.answer));modal.showModal();});}
const statusLabel={published:'已发布',draft:'草稿',offline:'已下架'};
const changed=r=>!!r.published&&r.status==='published'&&(JSON.stringify(r.draft)!==JSON.stringify(r.published)||JSON.stringify({category:r.category,order:r.order,experts:r.experts})!==JSON.stringify(r.publishedSettings||{category:r.category,order:r.order,experts:r.experts}));
function langPills(r){return `<div class="langs">${Object.entries(languages).map(([k,v])=>`<span title="${esc(v)} · ${!entered(r.draft[k])?'未录入':missing(r,r.draft[k]).length?'待完善':'已完善'}" class="lang-pill ${entered(r.draft[k])?(missing(r,r.draft[k]).length?'partial':'ready'):''}">${k.toUpperCase()}</span>`).join('')}</div>`;}
const label=r=>r.draft.zh.name||Object.values(r.draft).find(x=>x.name)?.name||(r.type==='qualifications'?'未命名资质':'未命名内容');
async function persist(){try{await writeState(state);return true}catch(e){toast(`保存失败：${e.message}`);return false}}
async function renderLogin(){let initialized=true;try{initialized=(await statusRequest()).initialized}catch{}app.innerHTML=`<div class="login"><section class="login-art">${brand()}<div class="login-copy"><div class="eyebrow">ONE SPACE. EVERY STORY.</div><h1>好内容，<br>值得被看见。</h1><p>从一份资质、一位专家，到一门好课程。<br>在这里管理内容，让每一次更新井然有序。</p></div><footer>EVOL DREAM · 内容管理工作台</footer></section><section class="login-form"><div class="eyebrow">${initialized?'WELCOME BACK':'FIRST TIME SETUP'}</div><h1>${initialized?'登录管理工作台':'创建主管理员'}</h1><p>${initialized?'管理公司资质、专家团队、课程与应用案例。':'第一次使用，请先设置主管理员账号。之后可以在“账号管理”里添加子账号。'}</p><form id="login-form">${initialized?'':'<div class="field"><label for="name">显示名称</label><input id="name" name="name" value="主管理员" required></div>'}<div class="field"><label for="account">账号</label><input id="account" name="account" autocomplete="username" required></div><div class="field"><label for="password">${initialized?'密码':'密码（至少 10 位）'}</label><input id="password" name="password" type="password" autocomplete="${initialized?'current-password':'new-password'}" required></div><div class="login-error" role="alert"></div><button class="primary" type="submit">${initialized?'登录管理工作台':'创建并登录'} ${icon('arrow')}</button></form><footer>仅限管理员使用 · 不开放公众注册</footer></section></div>`;document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const error=document.querySelector('.login-error');try{const data=new FormData(e.target);me=initialized?await loginRequest(data.get('account'),data.get('password')):await setupRequest(String(data.get('account')).trim(),data.get('name'),data.get('password'));sessionStorage.setItem('admin-login','1');section='overview';if(!me.mustChange)await loadWorkspace();afterLogin()}catch(reason){error.textContent=reason.message}};}
function shell(content){app.innerHTML=`<aside class="sidebar">${brand()}<div class="nav-label">工作空间 / WORKSPACE</div>${btn(`${icon('grid')}<span>内容总览</span>`,'nav:overview',`nav-btn ${section==='overview'?'active':''}`)}<div class="nav-label">内容管理 / CONTENT</div>${Object.entries(types).map(([k,v])=>btn(`${icon(kindIcon[k])}<span>${v}</span><b class="count">${state.records.filter(r=>r.type===k).length}</b>`,`nav:${k}`,`nav-btn ${section===k?'active':''}`)).join('')}${canLeads()?`<div class="nav-label">客户 / LEADS</div>${btn(`${icon('mail')}<span>咨询留言</span>${leads.some(l=>l.status==='new')?`<b class="count lead-count">${leads.filter(l=>l.status==='new').length}</b>`:''}`,'nav:leads',`nav-btn ${section==='leads'?'active':''}`)}`:''}${me?.role==='owner'?`<div class="nav-label">系统 / SYSTEM</div>${btn(`${icon('users')}<span>账号管理</span>`,'nav:users',`nav-btn ${section==='users'?'active':''}`)}`:''}<div class="side-bottom"><div class="user"><div class="avatar">${esc((me?.name||'管')[0])}</div><div><strong class="small">${esc(me?.name||'管理员')}</strong><div class="muted" style="font-size:10px">${roleLabel(me)}</div></div>${btn(icon('exit'),'logout','text-btn','aria-label="退出登录" title="退出登录"')}</div></div></aside><div class="layout"><header class="topbar"><div class="crumb">工作空间 <span>/ &nbsp;${editing?'编辑内容':section==='overview'?'内容总览':section==='users'?'账号管理':section==='leads'?'咨询留言':types[section]}</span></div><div class="top-actions"><span class="small muted"><i class="demo-dot"></i>本地独立后台</span>${btn(`${icon('shield')}修改密码`,'password','text-btn')}</div></header><main class="main">${content}</main></div>`;bindActions();}
// ===== 账号：登录、首次设置、修改密码、账号管理 =====
const canPublish=()=>!!me?.perms?.publish;
const roleLabel=u=>u?.role==='owner'?'主管理员':'子账号';
const tempPassword=()=>{const c='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';return Array.from(crypto.getRandomValues(new Uint32Array(12)),x=>c[x%c.length]).join('')};
function formDialog(title,message,fields,submitLabel,onSubmit){return new Promise(resolve=>{modal.style.width='';modal.innerHTML=`<form class="dialog-form" novalidate><div class="dialog-body"><div class="eyebrow">CONTENT STUDIO</div><h2>${esc(title)}</h2>${message?`<p>${esc(message)}</p>`:''}${fields}<div class="login-error" role="alert"></div></div><div class="dialog-actions"><button type="button" data-answer="cancel">取消</button><button type="submit" class="primary">${submitLabel}</button></div></form>`;const form=modal.querySelector('form'),close=v=>{modal.oncancel=null;modal.close();resolve(v)};modal.querySelector('[data-answer="cancel"]').onclick=()=>close(null);modal.oncancel=e=>{e.preventDefault();close(null)};form.onsubmit=async e=>{e.preventDefault();const error=form.querySelector('.login-error');error.textContent='';try{const result=await onSubmit(new FormData(form));close(result??true)}catch(reason){error.textContent=reason.message}};modal.showModal();form.querySelector('input')?.focus()})}
const permsHTML=(p={})=>`<div class="perm-group"><strong class="small">权限</strong><label class="selection"><input type="checkbox" name="publish" ${p.publish?'checked':''}><span>可以发布、下架、删除内容，设置首页展示</span></label><label class="selection"><input type="checkbox" name="leads" ${p.leads?'checked':''}><span>可以查看和处理咨询留言</span></label><label class="selection"><input type="checkbox" name="backup" ${p.backup?'checked':''}><span>可以创建备份</span></label><p class="help">都不勾选时，只能编辑内容、保存草稿，由主管理员检查后发布。</p></div>`;
const permsFrom=f=>({publish:f.get('publish')==='on',leads:f.get('leads')==='on',backup:f.get('backup')==='on'});
const passwordFields=(withOld=true)=>`${withOld?`<div class="field"><label for="old-password">原密码</label><input id="old-password" name="old" type="password" autocomplete="current-password"></div>`:''}<div class="field"><label for="new-password">新密码（至少 10 位）</label><input id="new-password" name="new" type="password" autocomplete="new-password"></div><div class="field"><label for="confirm-password">再次输入新密码</label><input id="confirm-password" name="confirm" type="password" autocomplete="new-password"></div>`;
const checkNew=f=>{if(String(f.get('new')||'').length<10)throw Error('新密码至少 10 位。');if(f.get('new')!==f.get('confirm'))throw Error('两次输入的新密码不一致。')};
// 必须改密的账号在改密前不能访问业务接口（后端返回 403），所以先判断 mustChange 再加载内容和留言
async function loadWorkspace(){state=await readState();[schema,options]=await Promise.all([getSchema(),getOptions()]);await refreshLeads()}
function afterLogin(){if(me?.mustChange)return renderForcePassword();renderAdmin()}
function renderForcePassword(){app.innerHTML=`<div class="login"><section class="login-art">${brand()}<div class="login-copy"><div class="eyebrow">ONE SPACE. EVERY STORY.</div><h1>欢迎加入，<br>${esc(me.name)}。</h1><p>这是你第一次登录。<br>请先把初始密码改成只有你自己知道的密码。</p></div><footer>EVOL DREAM · 内容管理工作台</footer></section><section class="login-form"><div class="eyebrow">SET YOUR PASSWORD</div><h1>设置新密码</h1><p>账号：${esc(me.account)}</p><form id="login-form">${passwordFields(true).replace('原密码','初始密码')}<div class="login-error" role="alert"></div><button class="primary" type="submit">保存并进入工作台 ${icon('arrow')}</button></form><footer>${btn('退出登录','logout','text-btn')}</footer></section></div>`;bindActions();document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),error=document.querySelector('.login-error');try{checkNew(f);me=await changePasswordRequest(f.get('old'),f.get('new'));await loadWorkspace();section='overview';toast('密码已更新');renderAdmin()}catch(reason){error.textContent=reason.message}}}
function renderUsers(){shell(`<div class="page-heading"><div><div class="eyebrow">TEAM ACCESS</div><h1>账号管理</h1><p>主管理员可以添加子账号，并决定每个子账号能否发布内容、创建备份。</p></div>${btn(`${icon('plus')}新增子账号`,'user-new','primary')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>账号</th><th>角色</th><th>权限</th><th>状态</th><th>最近登录</th><th style="text-align:right">操作</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="content-cell"><span class="avatar">${esc(u.name[0])}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.account)}</small></div></div></td><td><span class="badge ${u.role==='owner'?'good':''}">${roleLabel(u)}</span></td><td class="small">${u.role==='owner'?'全部权限':['编辑、保存草稿',u.perms.publish&&'发布 / 下架 / 删除 / 首页展示',u.perms.leads&&'查看咨询留言',u.perms.backup&&'创建备份'].filter(Boolean).join('<br>')}</td><td>${u.disabled?'<span class="badge">已停用</span>':u.mustChange?'<span class="badge warn">等待首次登录改密码</span>':'<span class="badge good">正常</span>'}</td><td class="muted small">${u.lastLoginAt?new Date(u.lastLoginAt).toLocaleString('zh-CN',{hour12:false}):'从未登录'}</td><td style="text-align:right;white-space:nowrap">${u.role==='owner'?btn('名称与账号',`user-edit:${u.id}`,'text-btn'):`${btn('账号与权限',`user-edit:${u.id}`,'text-btn')}${btn('重置密码',`user-reset:${u.id}`,'text-btn')}${btn(u.disabled?'启用':'停用',`user-toggle:${u.id}`,'text-btn')}${btn('删除',`user-delete:${u.id}`,'text-btn danger-link')}`}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>共 ${users.length} 个账号</span><span>子账号第一次登录时必须修改密码</span></div></section>`)}
async function userAction(act,arg){const u=users.find(x=>x.id===arg),reload=async()=>{users=await listUsersRequest();renderUsers()};
 if(act==='user-new'){const pw=tempPassword();const created=await formDialog('新增子账号','创建后把账号和初始密码告诉对方，对方第一次登录时必须改成自己的密码。',`<div class="field"><label>显示名称</label><input name="name" placeholder="例如：张三"></div><div class="field"><label>登录账号</label><input name="account" placeholder="英文字母或数字，例如 zhangsan"></div><div class="field"><label>初始密码</label><input name="password" value="${pw}"></div>${permsHTML()}`,'创建账号',async f=>({user:await createUserRequest({name:f.get('name'),account:String(f.get('account')||'').trim(),password:f.get('password'),perms:permsFrom(f)}),password:f.get('password')}));if(created){await reload();await ask('账号已创建','请把下面的登录信息告诉对方：',[['ok','知道了','primary']],[`登录账号：${created.user.account}`,`初始密码：${created.password}`])}return}
 if(act==='user-edit'){const owner=u.role==='owner';const saved=await formDialog(owner?'名称与账号':'账号与权限','修改登录账号后，对方需要用新账号登录，密码不变。',`<div class="field"><label>显示名称</label><input name="name" value="${esc(u.name)}"></div><div class="field"><label>登录账号</label><input name="account" value="${esc(u.account)}" placeholder="3-40 位英文字母、数字或 _ . @ -"></div>${owner?'':permsHTML(u.perms)}`,'保存',async f=>{const input={name:f.get('name'),account:String(f.get('account')||'').trim()};const user=await updateUserRequest(u.id,owner?input:{...input,perms:permsFrom(f)});if(user.id===me.id)me={...me,name:user.name,account:user.account};return user});if(saved){await reload();toast(saved.account!==u.account?`已保存，登录账号改为 ${saved.account}`:'已保存')}return}
 if(act==='user-reset'){const pw=tempPassword();const done=await formDialog(`重置 ${u.name} 的密码`,'重置后对方需要用新的初始密码登录，并重新设置自己的密码。',`<div class="field"><label>新的初始密码</label><input name="password" value="${pw}"></div>`,'重置密码',async f=>{await resetUserPasswordRequest(u.id,f.get('password'));return f.get('password')});if(done){await reload();await ask('密码已重置','请把新的初始密码告诉对方：',[['ok','知道了','primary']],[`登录账号：${u.account}`,`初始密码：${done}`])}return}
 if(act==='user-toggle'){if(await ask(u.disabled?`启用 ${u.name}？`:`停用 ${u.name}？`,u.disabled?'启用后对方可以重新登录。':'停用后对方会立即退出，不能再登录，账号和修改记录都会保留。')==='ok'){await updateUserRequest(u.id,{disabled:!u.disabled});await reload();toast(u.disabled?'已启用':'已停用')}return}
 if(act==='user-delete'){if(await ask(`删除 ${u.name}？`,'删除后这个账号不能再登录，内容上的修改记录仍会保留名字。此操作不能撤销。',[['cancel','取消'],['ok','确认删除','danger']])==='ok'){await removeUserRequest(u.id);await reload();toast('账号已删除')}return}
 if(act==='password'){if(await formDialog('修改密码','修改后，你在其他浏览器的登录会自动退出。',passwordFields(true),'保存新密码',async f=>{checkNew(f);me=await changePasswordRequest(f.get('old'),f.get('new'))}))toast('密码已修改');return}
}
// ===== 咨询留言 =====
const canLeads=()=>!!me?.perms?.leads;
const serviceLabel={training:'AI 人才培训',agents:'Agent 平台与部署',implementation:'AI 项目实施',partnerships:'合作交流'};
const leadStatusLabel={new:'新留言',contacted:'已联系',closed:'已完成'};
const langLabel={zh:'中文',en:'English',vi:'Tiếng Việt'};
let leadQuery='',leadFilter='';
async function refreshLeads(){if(canLeads())try{leads=await listLeadsRequest()}catch{}else leads=[]}
const contactLink=c=>/@/.test(c)?`<a href="mailto:${esc(c)}">${esc(c)}</a>`:`<a href="tel:${esc(c.replace(/[^\d+]/g,''))}">${esc(c)}</a>`;
function renderLeads(){const list=leads.filter(l=>(!leadFilter||l.status===leadFilter)&&(!leadQuery||`${l.id} ${l.name} ${l.company} ${l.contact} ${l.message}`.toLowerCase().includes(leadQuery.toLowerCase())));const fresh=leads.filter(l=>l.status==='new').length;
 shell(`<div class="page-heading"><div><div class="eyebrow">CUSTOMER LEADS</div><h1>咨询留言</h1><p>官网“联系我们”表单提交的咨询都会出现在这里。处理后记得标记状态，方便团队分工。</p></div>${leads.length?btn(`${icon('file')}导出表格`,'lead-export'):''}</div><section class="panel"><div class="toolbar"><div class="row"><label class="search">${icon('search')}<input id="lead-search" placeholder="搜索编号、姓名、公司、联系方式或留言" value="${esc(leadQuery)}" aria-label="搜索留言"></label><select id="lead-filter" aria-label="处理状态筛选"><option value="">全部状态</option>${Object.entries(leadStatusLabel).map(([v,t])=>`<option value="${v}" ${leadFilter===v?'selected':''}>${t}</option>`).join('')}</select></div><span class="small muted">共 ${leads.length} 条 · ${fresh} 条新留言</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>提交时间</th><th>联系人</th><th>联系方式</th><th>意向服务</th><th>留言</th><th>状态</th><th style="text-align:right">操作</th></tr></thead><tbody>${list.map(l=>`<tr><td class="muted small" style="white-space:nowrap">${new Date(l.createdAt).toLocaleString('zh-CN',{hour12:false})}<br><span style="font-size:10px">${langLabel[l.language]||''}页面</span></td><td><strong>${esc(l.name)}</strong><br><small class="muted">${esc(l.company)}</small></td><td class="small">${contactLink(l.contact)}</td><td class="small">${serviceLabel[l.service]||esc(l.service)}</td><td class="small"><div class="lead-message">${esc(l.message||'—')}</div></td><td><span class="badge ${l.status==='new'?'warn':l.status==='closed'?'good':''}">${leadStatusLabel[l.status]}</span>${l.handledBy?`<div class="status-note">${esc(l.handledBy)} 处理</div>`:''}</td><td style="text-align:right;white-space:nowrap">${btn('查看与处理',`lead-view:${l.id}`,'text-btn')}${me?.role==='owner'?btn('删除',`lead-delete:${l.id}`,'text-btn danger-link'):''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('file')}<h3>${leads.length?'没有符合条件的留言':'还没有收到咨询留言'}</h3><p>${leads.length?'换个关键词或状态试试。':'访客在官网“联系我们”提交表单后，会出现在这里。'}</p></div>`}<div class="list-note">目前留言只保存在网站服务器上，不会自动发邮件提醒；邮件通知需要甲方提供收件邮箱后开通。</div></section>`);
 const search=document.querySelector('#lead-search');search.oninput=e=>{leadQuery=e.target.value;const pos=e.target.selectionStart;renderLeads();const input=document.querySelector('#lead-search');input.focus();input.setSelectionRange(pos,pos)};document.querySelector('#lead-filter').onchange=e=>{leadFilter=e.target.value;renderLeads()}}
async function leadAction(act,arg){const l=leads.find(x=>x.id===arg);
 if(act==='lead-view'){const saved=await formDialog(`${l.name} · ${l.company}`,'',`<dl class="lead-detail"><dt>咨询编号</dt><dd>${esc(l.id)}</dd><dt>提交时间</dt><dd>${new Date(l.createdAt).toLocaleString('zh-CN',{hour12:false})}（${langLabel[l.language]||''}页面）</dd><dt>联系方式</dt><dd>${contactLink(l.contact)}</dd><dt>意向服务</dt><dd>${serviceLabel[l.service]||esc(l.service)}</dd><dt>留言内容</dt><dd style="white-space:pre-wrap">${esc(l.message||'—')}</dd></dl><div class="field"><label for="lead-status">处理状态</label><select id="lead-status" name="status">${Object.entries(leadStatusLabel).map(([v,t])=>`<option value="${v}" ${l.status===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="lead-note">内部备注（只在后台可见）</label><textarea id="lead-note" name="note" placeholder="例如：已电话沟通，下周发方案">${esc(l.note)}</textarea></div>${l.handledBy?`<p class="help">上次由 ${esc(l.handledBy)} 于 ${new Date(l.handledAt).toLocaleString('zh-CN',{hour12:false})} 处理</p>`:''}`,'保存',async f=>updateLeadRequest(l.id,{status:f.get('status'),note:f.get('note')}));if(saved){await refreshLeads();renderLeads();toast('已保存')}return}
 if(act==='lead-delete'){if(await ask('删除这条留言？','删除后无法恢复（备份中的旧记录除外）。一般只在客户要求删除个人信息时使用。',[['cancel','取消'],['ok','确认删除','danger']])==='ok'){await removeLeadRequest(l.id);await refreshLeads();renderLeads();toast('留言已删除')}return}
 if(act==='lead-export'){/* 以 = + - @ 开头的内容前加 '，防止 Excel 把访客填写的内容当成公式执行 */const cell=v=>{const s=String(v??''),safe=/^[=+\-@\t\r]/.test(s)?`'${s}`:s;return `"${safe.replace(/"/g,'""')}"`},rows=[['咨询编号','提交时间','姓名','公司','联系方式','意向服务','页面语言','留言','状态','内部备注','处理人'],...leads.map(l=>[l.id,new Date(l.createdAt).toLocaleString('zh-CN',{hour12:false}),l.name,l.company,l.contact,serviceLabel[l.service]||l.service,langLabel[l.language]||l.language,l.message,leadStatusLabel[l.status],l.note,l.handledBy])];const blob=new Blob(['﻿'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`咨询留言-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已导出表格');return}
}
function renderAdmin(){if(!sessionStorage.getItem('admin-login'))return renderLogin();if(editing)return renderEditor();if(section==='users')return renderUsers();if(section==='leads')return renderLeads();if(section==='overview')return renderOverview();renderList();}
function renderOverview(){const counts=Object.keys(types).map(k=>state.records.filter(r=>r.type===k).length);const drafts=state.records.filter(r=>r.status==='draft'||changed(r));shell(`<div class="page-heading"><div><div class="eyebrow">YOUR CONTENT, AT A GLANCE</div><h1>内容总览</h1><p>欢迎回来。把资料整理好，让每一次发布都更从容。</p></div><span class="muted small">2026 年 10 月 · 演示工作空间</span></div><div class="stats">${[...Object.entries(types).map(([k,v],i)=>({title:v,n:counts[i],note:`${state.records.filter(r=>r.type===k&&r.status==='published').length} 条已发布`,ic:kindIcon[k]})),{title:'待发布内容',n:drafts.length,note:'草稿与待发布修改',ic:'clock'}].map(s=>`<div class="stat"><div class="stat-head">${s.title}${icon(s.ic)}</div><strong>${String(s.n).padStart(2,'0')}</strong><small>${s.note}</small></div>`).join('')}</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h3>开始管理你的内容</h3><p>四个栏目，同一套清晰的发布流程</p></div>${icon('grid')}</div>${Object.entries(types).map(([k,v])=>`<div class="quick-card"><div class="quick-icon">${icon(kindIcon[k])}</div><div><h3>${v}</h3><p>${{qualifications:'资质证书逐条整理，选 3 张放在首页展示。',experts:'专家档案、专业背景与课程关联。',courses:'课程介绍、预览视频与下载资料。',cases:'行业应用案例三语整理，选 3 个放在首页展示。'}[k]}</p></div>${btn(icon('arrow'),`nav:${k}`,'text-btn',`aria-label="管理${v}"`)}</div>`).join('')}</section><section class="panel"><div class="panel-head"><h3>从上传到展示</h3><span class="badge good">4 个步骤</span></div><div class="steps">${[['上传资料','先放入图片或文件，文字可以稍后补充。'],['完善与预览','按中文、英文、越南文独立维护。'],['确认发布','检查必填项，发布后前台才会更新。'],['前台查看','已发布内容独立展示，草稿始终留在后台。']].map(([t,p],i)=>`<div class="step"><span>${i+1}</span><div><strong class="small">${t}</strong><p>${p}</p></div></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><h3>待处理内容</h3><p>继续上次未完成的整理</p></div><span class="badge warn">${drafts.length} 条待处理</span></div>${renderTable(drafts)}</section>`);}
function renderTable(records){if(!records.length)return `<div class="empty">${icon('file')}<h3>这里还没有内容</h3><p>新增一条记录，先上传资料也可以。</p></div>`;const isQ=!!records.length&&records.every(r=>r.type===records[0].type)&&!!featureTypes[records[0].type];return `<div class="table-wrap"><table><thead><tr><th>内容</th><th>语言完整度</th><th>发布状态</th>${isQ?'<th>首页展示</th>':''}<th>更新于</th><th style="text-align:right">操作</th></tr></thead><tbody>${records.sort((a,b)=>(b.featured?1:0)-(a.featured?1:0)||a.order-b.order).map(r=>`<tr><td><div class="content-cell">${r.draft.zh.image?`<img class="thumb" src="${mediaURL(r.draft.zh.image)}" alt="">`:`<span class="quick-icon">${icon(kindIcon[r.type])}</span>`}<div><strong>${esc(label(r))}</strong><small>${esc(types[r.type])} · ${esc(r.id)}</small></div></div></td><td>${langPills(r)}</td><td><span class="badge ${r.status==='published'?'good':r.status==='draft'?'warn':''}">${statusLabel[r.status]}</span>${changed(r)?'<div class="status-note">有未发布修改</div>':''}</td>${isQ?`<td>${!canPublish()?`<span class="small ${r.featured?'feature-toggle is-on':'muted'}">${r.featured?'★ 首页展示中':'—'}</span>`:r.status==='published'?btn(r.featured?'★ 首页展示中':'☆ 设为首页展示',`feature:${r.id}`,`text-btn feature-toggle ${r.featured?'is-on':''}`):'<span class="small muted">发布后可选</span>'}</td>`:''}<td class="muted small">${new Date(r.updated).toLocaleDateString('zh-CN')}<br><span style="font-size:10px">${r.updatedBy?`${esc(r.updatedBy)} 修改`:'本地更新记录'}</span></td><td style="text-align:right;white-space:nowrap">${btn('编辑',`edit:${r.id}`,'text-btn')}${btn('预览',`preview:${r.id}`,'text-btn')}${canPublish()?btn(r.status==='published'?'下架':'发布',`${r.status==='published'?'offline':'publish'}:${r.id}`,'text-btn')+btn('删除',`delete:${r.id}`,'text-btn danger-link'):''}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>共 ${records.length} 条记录</span><span>ZH 中文 &nbsp; EN 英文 &nbsp; VI 越南文</span></div>`;}
function renderList(){let records=state.records.filter(r=>r.type===section);const total=records.length;records=records.filter(r=>(!query||`${label(r)} ${r.id}`.toLowerCase().includes(query.toLowerCase()))&&(!statusFilter||(statusFilter==='pending'?changed(r):r.status===statusFilter)));shell(`<div class="page-heading"><div><div class="eyebrow">CONTENT LIBRARY</div><h1>${types[section]}</h1><p>${{qualifications:'一条资料，一份独立记录。先上传，再慢慢完善。',experts:'整理专家档案，连接专业背景与课程内容。',courses:'管理课程内容、学习预览和三语言资料。',cases:'每个案例一页，首页展示勾选的 3 个案例。'}[section]}</p></div>${btn(`${icon('plus')}新增${section==='qualifications'?'资料':section==='experts'?'专家':section==='cases'?'案例':'课程'}`,`new:${section}`,'primary')}</div><section class="panel"><div class="toolbar"><div class="row"><label class="search">${icon('search')}<input id="search" placeholder="搜索名称或内容 ID" value="${esc(query)}" aria-label="搜索内容"></label><select id="status-filter" aria-label="发布状态筛选"><option value="">全部状态</option>${[['published','已发布'],['draft','草稿'],['offline','已下架'],['pending','有未发布修改']].map(([v,t])=>`<option value="${v}" ${statusFilter===v?'selected':''}>${t}</option>`).join('')}</select></div><span class="small muted">共 ${total} 条内容</span></div>${renderTable(records)}<div class="list-note">${section==='qualifications'?'保存草稿不要求资料齐全，发布时检查名称、简介和资质图片。“首页展示”最多选 3 张，未选时首页显示最新发布的 3 张。':section==='cases'?'保存草稿不要求资料齐全，发布时检查必填项。“首页展示”最多选 3 个，未选时首页显示排在最前的 3 个。':'保存草稿不要求资料齐全，发布时才检查必填项。'} 每种语言的文字和媒体独立维护。</div></section>`);document.querySelector('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;renderList();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)};document.querySelector('#status-filter').onchange=e=>{statusFilter=e.target.value;renderList()};}
function field(key,title,value,{area=false,required=false,placeholder=''}={}){return `<div class="field" data-field="${key}"><label for="field-${key}">${title}${required?'<em>*</em>':''}</label>${area?`<textarea id="field-${key}" data-key="${key}" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input id="field-${key}" data-key="${key}" value="${esc(value)}" placeholder="${esc(placeholder)}">`}</div>`;}
function fileList(files,scope='attachments'){return files.map((f,i)=>`<div class="file-row">${icon('file')}<span class="name" title="${esc(f.name)}">${esc(f.displayName||f.name)}</span><small>${(f.size/1024/1024).toFixed(1)} MB</small>${btn('移除',`remove-file:${scope}:${i}`,'text-btn danger-link')}</div>`).join('');}
function uploader(slot,title,hint,file=null,clipIndex=null){const action=`upload:${slot}${clipIndex===null?'':`:${clipIndex}`}`;return `<div><div class="upload-box" data-action="${action}" role="button" tabindex="0" aria-label="${esc(title)}">${file?`${file.type?.startsWith('image/')?`<img src="${mediaURL(file)}" alt="${esc(title)}">`:icon('file')}<small>${esc(file.name)}</small><strong style="margin-top:7px">点击替换</strong>`:`${icon('upload')}<strong>${title}</strong><small>${hint}</small>`}</div>${file?btn('移除当前文件',`remove-media:${slot}:${clipIndex??''}`,'text-btn danger-link small'):''}</div>`;}
function renderEditor(){
 const r=editing;
 if(SCHEMA_TYPES.includes(r.type)&&schema){
  if(!schema.LANGS.includes(tab))tab='zh';
  ensureDraft(r,schema,options);
  const ui={icon,btn,mediaURL,statusLabel,changed,canPublish,label,types,languages};
  const ctx={record:r,tab,schema,options,records:state.records,ui,dirty,saved:state.records.some(x=>x.id===r.id),onChange:markDirty,rerender:renderEditor,setTab:lang=>{tab=lang;renderEditor()},toast,ask,openCourse:async id=>{if(!await leaveEditor())return;const target=state.records.find(x=>x.id===id);if(!target)return;editing=clone(target);tab='zh';dirty=false;renderEditor()}};
  section=r.type;
  shell(renderEditorPage(ctx));
  bindEditor(ctx);
  return;
 }
 return renderLegacyEditor();
}
function renderLegacyEditor(){const r=editing,v=r.draft[tab]||emptyLang(),original=state.records.find(x=>x.id===r.id);section=r.type;shell(`<a class="back" href="#" data-action="back">${icon('back')}返回${types[r.type]}</a><div class="page-heading"><div><div class="eyebrow">EDIT CONTENT</div><h1>${esc(label(r))}</h1><p>${esc(r.id)} &nbsp;·&nbsp; <span class="badge ${r.status==='published'?'good':'warn'}">${statusLabel[r.status]}</span> ${original&&changed(original)?'<span class="status-note">有未发布修改</span>':''}</p></div>${btn(`${icon('eye')}预览内容`,'preview-edit')}</div><div class="edit-layout"><section class="panel"><div class="tabs">${[...(featureTypes[r.type]?[]:[['base','基础设置']]),...Object.entries(languages)].map(([k,name])=>btn(`${name}${k!=='base'&&entered(r.draft[k])?'<i></i>':''}`,`tab:${k}`,`tab ${tab===k?'active':''}`)).join('')}</div><div class="panel-body">${tab==='base'?baseForm(r):langForm(r,v)}</div></section><aside class="edit-aside"><section class="panel"><div class="panel-head"><h3>资料完整度</h3>${icon('shield')}</div><div class="panel-body" id="completeness">${completeness(r)}</div></section><section class="panel"><div class="panel-head"><h3>三语言录入状态</h3></div><div class="panel-body" id="language-summary">${languageSummary(r)}</div></section><section class="panel"><div class="aside-note">${icon('info')}<br><strong style="color:var(--ink)">保存 ≠ 发布</strong><br>草稿只在后台可见。已发布内容的修改，确认再次发布后才会更新到前台。<br><br>文字和文件按语言分别保存，不会自动复制或翻译。</div></section></aside></div><div class="sticky-bottom"><div class="small muted" id="save-status">${dirty?'● 有未保存的修改':state.records.some(r=>r.id===editing.id)?'所有更改已保存于浏览器':'新内容，填写后请保存草稿'}<div style="font-size:10px">模拟数据 · 不写入真实站点</div></div><div class="actions">${btn('保存草稿','save')}${btn('预览','preview-edit')}${canPublish()?btn(`${icon('check')}发布内容`,'publish-edit','primary'):'<span class="small muted">你的账号只能保存草稿，发布请联系主管理员</span>'}</div></div>`);bindForm();}
function baseForm(r){return `<div class="section-label">基础设置<span class="badge">跨语言共用</span></div><p class="help">固定 ID、展示顺序与关联关系不随语言切换。</p><div class="field"><label>内容 ID</label><input value="${esc(r.id)}" disabled></div><div class="form-grid"><div class="field"><label for="sort-order">展示顺序</label><input id="sort-order" type="number" data-base="order" value="${r.order}"><small class="muted">数字越小越靠前</small></div></div>${r.type==='courses'?`<div class="separator"></div><div class="section-label">关联专家</div><p class="help">使用固定 ID 关联；前台仅显示当前语言已发布的专家。</p>${state.records.filter(x=>x.type==='experts').map(x=>`<label class="selection"><input type="checkbox" data-expert="${esc(x.id)}" ${r.experts.includes(x.id)?'checked':''}><span>${esc(label(x))}<small class="muted"> · ${esc(x.id)}</small></span></label>`).join('')||'<p class="help">暂无专家，请先新增专家档案。</p>'}`:''}<div class="separator"></div><div class="section-label">发布说明</div><p class="help">只需维护需要展示的语言，无需同时完成三种语言。发布时检查所有已录入语言的必要资料。</p>`;}
function caseForm(r,v){return `<div class="section-label">${languages[tab]}资料<span class="badge">${tab.toUpperCase()} 独立内容</span></div><p class="help">先上传资料也可以。红色 * 为发布时的必填项，草稿可随时保存。</p><div class="upload-grid">${uploader('image','上传案例图片','JPG / PNG / WebP · ≤ 10 MB',v.image)}<div><strong class="small">一张横向的案例图片</strong><p class="help" style="margin-top:10px">建议使用横图（约 3:1，例如 1600×532）。列表和详情页会按比例裁切显示。</p><div class="badge ${v.image?'good':''}">${v.image?'已选择图片':'尚未上传'}</div><div id="upload-progress"></div></div></div><div class="separator"></div><div class="section-label">案例介绍</div><div class="form-grid">${field('name','案例标题',v.name,{required:true,placeholder:'例如：AI 辅助设计与快速打样'})}${field('industry','行业',v.industry,{required:true,placeholder:'例如：LED 生产企业'})}</div>${field('description','简介',v.description,{area:true,required:true,placeholder:'一两句话说明这个案例做了什么，会显示在首页和案例列表'})}${field('problem','业务问题',v.problem,{area:true,required:true})}${field('steps','应用方式（每行一步）',v.steps,{area:true,required:true,placeholder:'每行写一个步骤，前台会自动编号'})}${field('people','人员分工',v.people,{area:true,required:true})}${field('deliverables','交付成果（每行一项）',v.deliverables,{area:true,required:true,placeholder:'每行写一项，首页最多显示前 3 项'})}${field('highlight','一句话亮点（可选）',v.highlight,{area:true})}${field('evaluation','评估重点（可选）',v.evaluation,{area:true})}`;}
function langForm(r,v){if(r.type==='cases')return caseForm(r,v);const isQ=r.type==='qualifications',isE=r.type==='experts',isC=r.type==='courses';return `<div class="section-label">${languages[tab]}资料<span class="badge">${tab.toUpperCase()} 独立内容</span></div><p class="help">先上传资料也可以。红色 * 为发布时的必填项，草稿可随时保存。</p><div class="upload-grid">${uploader('image',isE?'上传专家照片':isC?'上传课程封面':'上传资质图片','JPG / PNG / WebP · ≤ 10 MB',v.image)}<div><strong class="small">${isE?'让访客认识这位专家':isC?'一张清晰的课程封面':'一张清晰的资质图片'}</strong><p class="help" style="margin-top:10px">${isQ?'图片按原比例完整展示，不裁切。':isE?'照片和介绍按语言分别维护。':'封面与视频分别维护。视频预览片段可自由添加，不限数量。'}</p><div class="badge ${v.image?'good':''}">${v.image?'已选择图片':'尚未上传'}</div><div id="upload-progress"></div><label class="small muted" style="display:block;margin-top:12px"><input type="checkbox" id="simulate-fail" ${simulateFail?'checked':''}> 演示下一次上传失败</label></div></div><div class="separator"></div><div class="section-label">文字资料</div><div class="form-grid">${field('name',isE?'姓名':'名称',v.name,{required:true,placeholder:'请输入'})}${isE?field('org','所属高校 / 机构',v.org,{placeholder:'按真实公开资料填写'}):isC?field('category','课程分类',v.category||''):''}${isE?field('role','职务',v.role):isC?field('audience','适用对象',v.audience):''}${isE?field('education','学历',v.education):isC?field('goals','课程目标',v.goals):''}</div>${field('description',isQ?'简短说明':'简介',v.description,{area:true,required:true,placeholder:'只填写可公开的真实内容'})}${isE?field('background','专业背景',v.background,{area:true})+field('research','研究方向',v.research,{area:true})+field('experience','AI 教学 / 研究 / 实践经历',v.experience,{area:true}):''}${isC?field('outline','课程大纲',v.outline,{area:true}):''}${isQ?'':`<div class="separator"></div><div class="section-label">公开下载资料${btn(`${icon('plus')}添加附件`,'upload:attachments','text-btn')}</div><p class="help">PDF / DOCX / XLSX / PPTX · 单个 ≤ 30 MB · 仅发布后在前台展示</p><div class="file-list">${fileList(v.attachments)}</div>${v.attachments.length?v.attachments.map((f,i)=>`<div class="field" style="margin-top:13px"><label>附件 ${i+1} 的公开显示名称</label><input data-attachment-name="${i}" value="${esc(f.displayName||'')}" placeholder="不填写时显示“查看原件”或“下载资料”"></div>`).join(''):'<div class="small muted">尚未添加附件</div>'}`}${isC?`<div class="separator"></div><div class="section-label">学习预览片段<span class="badge">${v.clips.length} 个 · 数量不限</span></div><p class="help">视频与封面均为 16:9。MP4 · H.264 / AAC · 单个 ≤ 30 MB。上传时检查类型、大小和画面比例。</p>${v.clips.map((clip,i)=>`<div class="clip"><div class="clip-head"><strong class="small">片段 ${i+1}</strong><div class="row">${btn('↑',`clip-up:${i}`,'text-btn',`aria-label="上移片段 ${i+1}"`)}${btn('↓',`clip-down:${i}`,'text-btn',`aria-label="下移片段 ${i+1}"`)}${btn('删除',`clip-delete:${i}`,'text-btn danger-link')}</div></div><div class="field"><label>片段标题</label><input data-clip-title="${i}" value="${esc(clip.title)}" placeholder="输入片段标题"></div><div class="upload-grid">${uploader('clip-video','上传视频','MP4 · 16:9 · ≤ 30 MB',clip.video,i)}${uploader('clip-cover','上传视频封面','16:9 · ≤ 10 MB',clip.cover,i)}</div></div>`).join('')}${btn(`${icon('plus')}添加预览片段`,'clip-add','', 'style="width:100%;border-style:dashed"')}`:''}`;}
function completeness(r){const k=tab==='base'?'zh':tab,v=r.draft[k],m=missing(r,v);if(!entered(v))return `<span class="badge">未录入</span><p class="help" style="margin-top:14px">先上传图片或填写文字，即可开始整理${languages[k]}资料。</p>`;return `<span class="badge ${m.length?'warn':'good'}">${m.length?'待补充':'已完善'}</span>${m.length?m.map(x=>`<div class="checkline warn">${icon('info')}<span>待补充：${esc(x)}</span></div>`).join(''):`<div class="checkline good">${icon('check')}当前语言的主要资料已齐全</div>`}<p class="help" style="margin-bottom:0">保存草稿不受限制，发布时检查必填项。</p>`;}
function languageSummary(r){return Object.entries(languages).map(([k,v])=>`<div class="lang-status"><span>${v}</span><span class="badge ${!entered(r.draft[k])?'':missing(r,r.draft[k]).length?'warn':'good'}">${!entered(r.draft[k])?'未录入':missing(r,r.draft[k]).length?'待完善':'已完善'}</span></div>`).join('');}
function markDirty(){dirty=true;const status=document.querySelector('#save-status');if(status)status.innerHTML='● 有未保存的修改<div style="font-size:10px">尚未写入本地后台</div>';const complete=document.querySelector('#completeness');if(complete)complete.innerHTML=completeness(editing);const summary=document.querySelector('#language-summary');if(summary)summary.innerHTML=languageSummary(editing);}
function bindForm(){document.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{editing.draft[tab][el.dataset.key]=el.value;markDirty()});document.querySelectorAll('[data-base]').forEach(el=>el.onchange=()=>{editing[el.dataset.base]=el.dataset.base==='order'?Number(el.value):el.value;markDirty()});document.querySelectorAll('[data-expert]').forEach(el=>el.onchange=()=>{editing.experts=Array.from(document.querySelectorAll('[data-expert]:checked'),x=>x.dataset.expert);markDirty()});document.querySelectorAll('[data-clip-title]').forEach(el=>el.oninput=()=>{editing.draft[tab].clips[+el.dataset.clipTitle].title=el.value;markDirty()});document.querySelectorAll('[data-attachment-name]').forEach(el=>el.oninput=()=>{editing.draft[tab].attachments[+el.dataset.attachmentName].displayName=el.value;markDirty()});const fail=document.querySelector('#simulate-fail');if(fail)fail.onchange=()=>simulateFail=fail.checked;document.querySelectorAll('.upload-box').forEach(el=>{el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}};el.ondragover=e=>{e.preventDefault();el.style.borderColor='#21785b'};el.ondragleave=()=>el.style.borderColor='';el.ondrop=async e=>{e.preventDefault();el.style.borderColor='';const [,slot,idx]=el.dataset.action.split(':');await uploadFiles(Array.from(e.dataTransfer.files),slot,idx===undefined?null:+idx)}});}
async function saveEditing(quiet=false){if(busy)return false;busy=true;const old=clone(state),copy=clone(editing);copy.updated=new Date().toISOString();const idx=state.records.findIndex(r=>r.id===copy.id);if(idx<0)state.records.push(copy);else state.records[idx]=copy;if(!await persist()){state=old;busy=false;return false}editing=clone(state.records.find(r=>r.id===copy.id)||copy);dirty=false;busy=false;if(!quiet)toast('草稿已保存，前台内容没有变化');return true;}
async function leaveEditor(){if(!dirty)return true;const answer=await ask('有尚未保存的修改','是否保存当前修改后继续？',[['cancel','取消'],['discard','放弃修改'],['save','保存并继续','primary']]);if(answer==='cancel')return false;if(answer==='save'&&!await saveEditing(true))return false;return true;}
async function publish(record,fromEditor=false){
 if(busy)return;
 if(fromEditor||(editing&&editing.id===record.id)){if(!await saveEditing(true))return;record=editing}
 busy=true;
 try{
  const published=await publishRecord(record.id);
  const idx=state.records.findIndex(r=>r.id===published.id);
  if(idx<0)state.records.push(published);else state.records[idx]=published;
  if(editing&&editing.id===published.id){editing=clone(published);dirty=false}
  busy=false;renderAdmin();
  const names={zh:'中文',vi:'越南语',en:'英文'};
  const langs=(schema?.LANGS||['zh','vi','en']).map(l=>{const x=published.report?.languages?.[l];return `${names[l]}：${x?.show?'会显示':'不会显示'+(x?.missing?.length?`，缺 ${x.missing.join('、')}`:'')}`});
  await ask('已发布','前台刷新后即可看到这一版。',[['ok','知道了','primary']],langs);
 }catch(error){
  busy=false;
  const lines=String(error.message||'发布失败。').split('\n').map(x=>x.replace(/^·\s*/,'').trim()).filter(Boolean);
  await ask('还不能发布','下面这些改好后才能发布：',[['ok','去修改','primary']],lines);
 }
}
async function uploadFiles(files,slot,clipIndex){if(!files.length||busy)return;const expectedTab=tab,expectedID=editing.id;busy=true;try{for(const file of files){const isImg=slot==='image'||slot==='clip-cover',isVideo=slot==='clip-video',ext=file.name.split('.').pop().toLowerCase();if(!(isImg?['jpg','jpeg','png','webp']:isVideo?['mp4']:['pdf','docx','xlsx','pptx']).includes(ext)){toast('文件格式不支持，请按上传区提示选择');continue}if(file.size>(isImg?10:30)*1024*1024){toast(`文件过大：本区域上限 ${isImg?10:30} MB`);continue}const bar=document.querySelector('#upload-progress');if(bar)bar.innerHTML=`<div class="progress-label">正在上传 ${esc(file.name)}</div><div class="upload-progress"><span style="width:30%"></span></div>`;let dims;if(isImg||isVideo){dims=await getDimensions(file,isVideo);if(!dims){toast('无法读取该文件，请选择浏览器可识别的图片或视频');continue}if((slot==='clip-cover'||isVideo)&&Math.abs(dims.w/dims.h-16/9)>.025){toast('此片段媒体不是 16:9，请调整后重新选择');continue}}const saved=await uploadRequest(file);if(bar?.querySelector('span'))bar.querySelector('span').style.width='100%';if(!editing||editing.id!==expectedID||tab!==expectedTab)break;const media={...saved,type:saved.mime,displayName:'',dimensions:dims||null};const v=editing.draft[tab];if(slot==='image')v.image=media;else if(slot==='attachments')v.attachments.push(media);else if(v.clips[clipIndex])v.clips[clipIndex][slot==='clip-video'?'video':'cover']=media;dirty=true;toast('文件已上传到本地后台，点击保存草稿后写入内容');}}catch(error){toast(`文件上传失败：${error.message}`)}finally{busy=false;renderEditor();}}
async function getDimensions(file,video){return new Promise(resolve=>{const url=URL.createObjectURL(file),el=document.createElement(video?'video':'img');let done=false;const finish=value=>{if(done)return;done=true;clearTimeout(timer);URL.revokeObjectURL(url);resolve(value)};const timer=setTimeout(()=>finish(null),8000);el[video?'onloadedmetadata':'onload']=()=>finish({w:video?el.videoWidth:el.naturalWidth,h:video?el.videoHeight:el.naturalHeight});el.onerror=()=>finish(null);if(video)el.preload='metadata';el.src=url;});}
function pickFile(slot,index){const input=document.createElement('input');input.type='file';input.multiple=slot==='attachments';input.accept=slot==='image'||slot==='clip-cover'?'.jpg,.jpeg,.png,.webp':slot==='clip-video'?'.mp4':'.pdf,.docx,.xlsx,.pptx';input.onchange=()=>uploadFiles(Array.from(input.files),slot,index);input.click();}
function bindActions(){app.querySelectorAll('[data-action]').forEach(el=>el.onclick=async e=>{e.preventDefault();if(busy){toast('正在处理文件，请稍候');return}await action(el.dataset.action)});}
async function action(value){const [act,arg,arg2]=value.split(':');
 if(act==='logout'){if(!await leaveEditor())return;editing=null;dirty=false;await logoutRequest();me=null;section='overview';sessionStorage.removeItem('admin-login');renderLogin();return}
 if(act==='nav'||act==='back'){if(!await leaveEditor())return;editing=null;dirty=false;section=act==='back'?section:arg;query='';statusFilter='';try{if(section==='users')users=await listUsersRequest();else if(section==='leads')await refreshLeads();else state=await readState();if(section!=='leads')await refreshLeads()}catch(e){toast(e.message)}renderAdmin();return}
 if(act.startsWith('lead-')){try{await leadAction(act,arg)}catch(e){toast(e.message)}return}
 if(act.startsWith('user-')||act==='password'){try{await userAction(act,arg)}catch(e){toast(e.message)}return}
 if(act==='new'){editing=makeRecord(arg);if(SCHEMA_TYPES.includes(arg)&&schema){ensureDraft(editing,schema,options);tab='zh'}else tab=featureTypes[arg]?'zh':'base';dirty=false;renderEditor();return}
 if(act==='edit'){editing=clone(state.records.find(r=>r.id===arg));tab='zh';dirty=false;renderEditor();return}
 if(act==='tab'){if(tab===arg)return;if(SCHEMA_TYPES.includes(editing?.type)){tab=arg;renderEditor();return}if(!await leaveEditor())return;if(dirty){const saved=state.records.find(r=>r.id===editing.id);editing=saved?clone(saved):makeRecord(editing.type);dirty=false}tab=arg;renderEditor();return}
 if(act==='save'){if(await saveEditing())renderEditor();return}
 if(act==='publish-edit'){await publish(editing,true);return}
 if(act==='publish'){await publish(state.records.find(r=>r.id===arg));return}
 if(act==='offline'){if(await ask('下架这条内容？','下架后不再出现在前台页面，资料仍可在后台编辑。')==='ok'){const old=clone(state),record=state.records.find(r=>r.id===arg);record._action='offline';if(!await persist())state=old;renderAdmin();toast('已下架')}return}
 if(act==='feature'){const r=state.records.find(r=>r.id===arg),[u,n]=featureTypes[r.type];if(!r.featured&&state.records.filter(x=>x.type===r.type&&x.featured).length>=3){await ask(`首页最多展示 3 ${u}`,`请先取消一${u}“首页展示中”的${n}，再选择这一${u}。`,[['ok','知道了','primary']]);return}const old=clone(state),on=!r.featured;r.featured=on;if(!await persist())state=old;renderAdmin();toast(on?'已设为首页展示':'已取消首页展示');return}
 if(act==='delete'){const r=state.records.find(r=>r.id===arg);if(r.status==='published'){await ask('请先下架内容','已发布内容需要先下架，再执行删除。',[['ok','知道了','primary']]);return}if(await ask('删除这条记录？','删除后无法撤销（备份中的旧记录除外）。',[['cancel','取消'],['ok','确认删除','danger']])==='ok'){const old=clone(state);state.records=state.records.filter(r=>r.id!==arg);if(!await persist())state=old;renderAdmin();toast('记录已删除')}return}
 if(act==='upload'){pickFile(arg,arg2===undefined?null:+arg2);return}
 if(act==='remove-media'){if(await ask('移除当前文件？',`仅移除 ${languages[tab]} 草稿的当前文件，不影响其他语言或上一版已发布内容。`)!='ok')return;const v=editing.draft[tab];if(arg==='image')v.image=null;else v.clips[+arg2][arg==='clip-video'?'video':'cover']=null;dirty=true;renderEditor();return}
 if(act==='remove-file'){if(await ask('移除当前语言的附件？','不会移除其他语言的附件，已发布版本会保留至再次发布。')==='ok'){editing.draft[tab].attachments.splice(+arg2,1);dirty=true;renderEditor()}return}
 if(act==='clip-add'){editing.draft[tab].clips.push({title:'',video:null,cover:null});dirty=true;renderEditor();return}
 if(act==='clip-delete'){if(await ask('删除此预览片段？','仅影响当前语言的草稿。')==='ok'){editing.draft[tab].clips.splice(+arg,1);dirty=true;renderEditor()}return}
 if(act==='clip-up'||act==='clip-down'){const clips=editing.draft[tab].clips,i=+arg,j=act==='clip-up'?i-1:i+1;if(j>=0&&j<clips.length){[clips[i],clips[j]]=[clips[j],clips[i]];dirty=true;renderEditor()}return}
 if(act==='preview'||act==='preview-edit'){previewRecord=clone(act==='preview'?state.records.find(r=>r.id===arg):editing);previewLang=tab==='base'?'zh':tab;showPreview();return}
}
function recordPublic(r,lang,preview=false){return (preview?r.draft:r.published)?.[lang];}
function publicTitle(type,lang){return {zh:{qualifications:'公司资质',experts:'专家及讲师团队',courses:'AI 课程',cases:'应用案例'},en:{qualifications:'Company qualifications',experts:'Experts & Instructors',courses:'AI Courses',cases:'Use cases'},vi:{qualifications:'Hồ sơ năng lực',experts:'Chuyên gia & Giảng viên',courses:'Khóa học AI',cases:'Tình huống ứng dụng'}}[lang][type];}
function copy(lang,key){return {zh:{original:'查看原件',download:'下载资料',detail:'查看详情',empty:'此语言暂无已发布内容',back:'返回列表',clips:'学习预览',outline:'课程大纲',experts:'关联专家',courses:'关联课程',intro:'简介'},en:{original:'View document',download:'Download',detail:'View details',empty:'No published content in this language',back:'Back to list',clips:'Course previews',outline:'Course outline',experts:'Instructors',courses:'Related courses',intro:'Introduction'},vi:{original:'Xem tài liệu',download:'Tải tài liệu',detail:'Xem chi tiết',empty:'Chưa có nội dung bằng ngôn ngữ này',back:'Quay lại',clips:'Xem trước',outline:'Nội dung khóa học',experts:'Giảng viên',courses:'Khóa học liên quan',intro:'Giới thiệu'}}[lang][key];}
function attachmentLinks(v,lang,isQ){return v.attachments.map(f=>`<a href="${mediaURL(f)}" download="${esc(f.displayName||'document')}">${esc(f.displayName||copy(lang,isQ?'original':'download'))} ↗</a>`).join(' &nbsp; ');}
function cardHTML(r,lang,preview=false,detail=false){const v=recordPublic(r,lang,preview);if(!entered(v))return '';const q=r.type==='qualifications',e=r.type==='experts';return `<article class="public-card ${q?'qual':''} ${e?'expert':''} ${q&&!v.image?'no-image':''}">${v.image?`<img src="${mediaURL(v.image)}" alt="${esc(v.name||publicTitle(r.type,lang))}">`:''}<div class="body"><div class="eyebrow">${q?esc(publicTitle(r.type,lang)):e?'EXPERT PROFILE':'AI LEARNING'}</div><h2>${esc(v.name||(q?publicTitle(r.type,lang):''))}</h2>${v.org?`<p>${esc(v.org)}</p>`:''}${v.role?`<p>${esc(v.role)}</p>`:''}${v.validity?`<span class="badge">${esc(v.validity)}</span>`:''}${v.number?`<p>${esc(v.number)}</p>`:''}${v.description?`<p>${esc(v.description)}</p>`:''}${q?`${v.responsibility?`<p>${esc(v.responsibility)}</p>`:''}${v.results?`<p>${esc(v.results)}</p>`:''}`:''}${attachmentLinks(v,lang,q)}${!q&&!detail?`<div style="margin-top:15px">${btn(`${copy(lang,'detail')} ${icon('arrow')}`,`detail:${r.id}`,'text-btn')}</div>`:''}</div></article>`;}
function detailHTML(r,lang,preview=false){const v=recordPublic(r,lang,preview);if(!entered(v))return `<div class="empty"><h3>${copy(lang,'empty')}</h3></div>`;if(r.type==='qualifications')return cardHTML(r,lang,preview,true);const related=r.type==='courses'?(r.experts||[]).map(id=>state.records.filter(x=>x.status==='published').find(x=>x.id===id)).filter(x=>x&&entered(x.published?.[lang])):state.records.filter(x=>x.status==='published').filter(x=>x.type==='courses'&&x.experts?.includes(r.id)&&entered(x.published?.[lang]));return `<div class="detail-layout"><div>${cardHTML(r,lang,preview,true)}${v.clips.length?`<section class="panel" style="margin-top:20px"><div class="panel-head"><h3>${copy(lang,'clips')}</h3></div><div class="panel-body video-grid">${v.clips.map(c=>`<div class="video-tile">${c.video?`<video controls preload="metadata" src="${mediaURL(c.video)}" ${c.cover?`poster="${mediaURL(c.cover)}"`:''}></video>`:`<div class="empty">尚未添加视频</div>`}<h4>${esc(c.title)}</h4></div>`).join('')}</div></section>`:''}</div><div>${[['outline',copy(lang,'outline')],['audience',lang==='zh'?'适用对象':'Audience'],['goals',lang==='zh'?'课程目标':'Goals'],['education',lang==='zh'?'学历':'Education'],['background',lang==='zh'?'专业背景':'Background'],['research',lang==='zh'?'研究方向':'Research'],['experience',lang==='zh'?'AI 经历':'AI experience']].filter(([k])=>v[k]).map(([k,title])=>`<section class="panel"><div class="panel-head"><h3>${title}</h3></div><div class="panel-body detail-text small">${esc(v[k])}</div></section>`).join('')}${related.length?`<section class="panel"><div class="panel-head"><h3>${copy(lang,r.type==='courses'?'experts':'courses')}</h3></div><div class="panel-body">${related.map(x=>btn(esc(x.published[lang].name),`detail:${x.id}`,'text-btn')).join('')}</div></section>`:''}</div></div>`;}
function showPreview(){const r=previewRecord;modal.innerHTML=`<div class="panel-head"><div><h3>内容预览</h3><p>当前草稿 · 未发布修改也会显示于此</p></div><div class="row"><select id="preview-language" aria-label="预览语言">${Object.entries(languages).map(([k,v])=>`<option value="${k}" ${previewLang===k?'selected':''}>${v}</option>`).join('')}</select><button id="close-preview" aria-label="关闭预览">×</button></div></div><div class="preview-shell">${detailHTML(r,previewLang,true)||`<div class="empty">${copy(previewLang,'empty')}</div>`}</div><div class="dialog-actions"><button id="preview-done" class="primary">返回编辑</button></div>`;modal.style.width='960px';document.querySelector('#close-preview').onclick=document.querySelector('#preview-done').onclick=()=>{modal.close();modal.style.width=''};document.querySelector('#preview-language').onchange=e=>{previewLang=e.target.value;showPreview()};modal.querySelectorAll('[data-action^="detail:"]').forEach(b=>b.onclick=()=>toast('关联目标将跳转到其已发布详情；可在本地前台查看'));if(!modal.open)modal.showModal();}
try{me=await meRequest();if(!me.mustChange)await loadWorkspace();sessionStorage.setItem('admin-login','1');afterLogin()}catch{sessionStorage.removeItem('admin-login');renderLogin()}
addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue=''}});
